"""PluginSystem — 轻量插件注册表。

借鉴 deepseek-harness 的 Cordis 插件系统（轻量版）：
- 每个插件有 activate/deactivate 生命周期
- 通过 PluginContext 注册服务和事件监听
- 支持可逆卸载（effect 清理）

不需要完整 Cordis 的复杂度，仅提供：
- 服务注册与发现
- 事件发布/订阅
- 插件生命周期管理
"""
import logging
from typing import Any, Callable

logger = logging.getLogger("agent.plugin")


class PluginContext:
    """插件上下文 — 插件通过它与核心交互。

    每个插件在 activate() 时收到一个 PluginContext，
    可以注册服务、监听事件、注册钩子。
    deactivate() 时自动清理所有注册的 effect。
    """

    def __init__(self, plugin_name: str, bus: 'PluginBus'):
        self._plugin_name = plugin_name
        self._bus = bus
        self._effects: list = []   # 清理回调列表

    @property
    def plugin_name(self) -> str:
        return self._plugin_name

    def register_service(self, name: str, service: Any):
        """注册一个服务（可被其他插件消费）。"""
        self._bus._services[name] = service
        self._effects.append(lambda: self._bus._services.pop(name, None))
        logger.debug('[%s] 注册服务: %s', self._plugin_name, name)

    def get_service(self, name: str) -> Any:
        """获取已注册的服务。"""
        return self._bus._services.get(name)

    def on(self, event: str, handler: Callable):
        """注册事件监听。"""
        self._bus._subscribe(event, handler, owner=self._plugin_name)
        self._effects.append(
            lambda: self._bus._unsubscribe(event, handler))
        logger.debug('[%s] 监听事件: %s', self._plugin_name, event)

    def emit(self, event: str, *args, **kwargs):
        """发布事件。"""
        self._bus.emit(event, *args, **kwargs)

    def add_hook(self, seam: str, hook: Callable, priority: int = 100):
        """注册到指定接缝的钩子链。"""
        self._bus._add_hook(seam, hook, priority, owner=self._plugin_name)
        self._effects.append(
            lambda: self._bus._remove_hook(seam, hook))

    def _cleanup(self):
        """清理所有注册的 effect（反序执行）。"""
        for effect in reversed(self._effects):
            try:
                effect()
            except Exception:
                logger.exception('[%s] effect 清理异常', self._plugin_name)
        self._effects.clear()


class PluginBus:
    """插件总线 — 管理所有插件的服务、事件和钩子。"""

    def __init__(self):
        self._services: dict[str, Any] = {}
        self._subscribers: dict[str, list[tuple[str, Callable]]] = {}
        self._hooks: dict[str, list[tuple[int, str, Callable]]] = {}

    def _subscribe(self, event: str, handler: Callable, owner: str):
        if event not in self._subscribers:
            self._subscribers[event] = []
        self._subscribers[event].append((owner, handler))

    def _unsubscribe(self, event: str, handler: Callable):
        subs = self._subscribers.get(event, [])
        self._subscribers[event] = [
            (o, h) for o, h in subs if h is not handler]

    def emit(self, event: str, *args, **kwargs):
        """发布事件（异常隔离）。"""
        for owner, handler in self._subscribers.get(event, []):
            try:
                handler(*args, **kwargs)
            except Exception:
                logger.exception('[%s] 事件处理器异常: %s（已隔离）',
                                 owner, event)

    def _add_hook(self, seam: str, hook: Callable, priority: int, owner: str):
        if seam not in self._hooks:
            self._hooks[seam] = []
        self._hooks[seam].append((priority, owner, hook))
        self._hooks[seam].sort(key=lambda x: x[0])

    def _remove_hook(self, seam: str, hook: Callable):
        hooks = self._hooks.get(seam, [])
        self._hooks[seam] = [
            (p, o, h) for p, o, h in hooks if h is not hook]

    def run_hooks(self, seam: str, *args, **kwargs):
        """执行接缝上的钩子链（waterfall 模式）。

        如果钩子返回非 None 值，该值作为结果返回（短路）。
        否则继续执行下一个钩子。
        """
        for priority, owner, hook in self._hooks.get(seam, []):
            try:
                result = hook(*args, **kwargs)
                if result is not None:
                    return result
            except Exception:
                logger.exception('[%s] 钩子异常: %s（已隔离）',
                                 owner, seam)
        return None


class Plugin:
    """插件基类。

    子类覆写 activate() 和 deactivate() 实现自定义逻辑。
    """

    name: str = 'unnamed'
    version: str = '1.0.0'
    description: str = ''

    def activate(self, ctx: PluginContext):
        """激活插件（注册服务、监听事件等）。"""
        pass

    def deactivate(self):
        """停用插件（可选的自定义清理）。"""
        pass


class PluginManager:
    """插件管理器 — 管理插件的完整生命周期。

    用法：
        manager = PluginManager()
        manager.register(MyPlugin())
        manager.activate_all()
        # ... 运行中 ...
        manager.deactivate_all()
    """

    def __init__(self):
        self._bus = PluginBus()
        self._plugins: dict[str, tuple[Plugin, PluginContext]] = {}

    @property
    def bus(self) -> PluginBus:
        return self._bus

    def register(self, plugin: Plugin) -> bool:
        """注册一个插件。"""
        if plugin.name in self._plugins:
            logger.warning('插件已存在: %s', plugin.name)
            return False
        ctx = PluginContext(plugin.name, self._bus)
        self._plugins[plugin.name] = (plugin, ctx)
        logger.info('注册插件: %s (v%s)', plugin.name, plugin.version)
        return True

    def unregister(self, name: str) -> bool:
        """注销插件（先 deactivate 再移除）。"""
        entry = self._plugins.get(name)
        if not entry:
            return False
        plugin, ctx = entry
        try:
            plugin.deactivate()
        except Exception:
            logger.exception('插件 %s deactivate 异常', name)
        ctx._cleanup()
        del self._plugins[name]
        logger.info('注销插件: %s', name)
        return True

    def activate_all(self):
        """激活所有已注册插件。"""
        for name, (plugin, ctx) in self._plugins.items():
            try:
                plugin.activate(ctx)
                logger.info('激活插件: %s', name)
            except Exception:
                logger.exception('插件 %s activate 失败', name)

    def deactivate_all(self):
        """停用所有插件（反序）。"""
        for name in reversed(list(self._plugins.keys())):
            plugin, ctx = self._plugins[name]
            try:
                plugin.deactivate()
            except Exception:
                logger.exception('插件 %s deactivate 异常', name)
            ctx._cleanup()

    def get(self, name: str) -> Plugin:
        """获取插件实例。"""
        entry = self._plugins.get(name)
        return entry[0] if entry else None

    def list_plugins(self) -> list:
        """列出所有已注册插件的摘要。"""
        return [
            {
                'name': plugin.name,
                'version': plugin.version,
                'description': plugin.description,
            }
            for plugin, _ in self._plugins.values()
        ]
